// Generated by .claude/workflow-src/build.mjs from ticket-batch.js; edit those files, not this one.
export const meta = {
  name: 'ticket-batch-fast',
  description: 'Ticket batch: Opus plan, Haiku build (Sonnet if Haiku fails), Opus review per chunk of up to 6 tickets, merge and e2e',
  whenToUse: 'A batch of approved tickets when speed matters; no per-ticket Sonnet review, one Opus reviewer per 6 tickets',
  phases: [
    { title: 'Plan', detail: 'Opus planner per chunk of tickets', model: 'opus' },
    { title: 'Build', detail: 'Haiku per ticket; Sonnet takes over when Haiku fails', model: 'haiku' },
    { title: 'Batch review', detail: 'Opus reviews each chunk, merges into develop and runs e2e', model: 'opus' },
  ],
}

const MODE = 'fast'

/*
 * args:
 *   date       today's date, yyyy-mm-dd (scripts cannot read the clock)
 *   tickets    [{ name, id, branch, answers? }] in merge order. name is the ticket file name without .md,
 *              branch is feat/<name> or fix/<name>, answers is an optional "## Answers" text from the product owner.
 *   ticketsDir optional folder (outside the repo) with approved drafts <name>.md; otherwise each ticket is read from
 *              practice/tally/tickets/todo/ or backlog/ on develop.
 *   chunkSize  tickets per Opus planner / batch reviewer, default 6
 *   fixBranch  branch for cross-ticket fixes, default fix/batch-review-<date>
 *   e2ePort    port for the final e2e run, default 5196
 * Paths in prompts are relative to the repository root (the main checkout, which stays on develop).
 */

const A = args || {}
if (!A.date || !Array.isArray(A.tickets) || !A.tickets.length) {
  return { error: 'args.date (yyyy-mm-dd) and args.tickets [{name, id, branch}] are required' }
}
const TICKETS = A.tickets
const CHUNK = Math.max(1, A.chunkSize || 6)
const FIX_BRANCH = A.fixBranch || `fix/batch-review-${A.date}`
const E2E_PORT = A.e2ePort || 5196
const wtOf = branch => `.scratch/wt/${branch.replace(/\//g, '-').replace(/_/g, '-')}`
const chunks = []
for (let i = 0; i < TICKETS.length; i += CHUNK) chunks.push(TICKETS.slice(i, i + CHUNK))
const ticketSource = t => A.ticketsDir
  ? `the approved draft ${A.ticketsDir}/${t.name}.md (outside the repo; read it with the Read tool and copy it into the branch)`
  : `practice/tally/tickets/todo/${t.name}.md (or backlog/) on develop`
const listOf = ts => ts.map(t => `- ${t.id} ${t.name} (branch ${t.branch}, worktree ${wtOf(t.branch)})`).join('\n')

const COMMON = `
Commit identity: read git config user.name and user.email once in the main checkout, then pass them explicitly with -c user.name="..." -c user.email="..." on every commit and merge (never rely on the worktree's config), as author and committer. Never an AI identity. No Co-Authored-By trailer, no "Generated with" footer. Small conventional commits (feat:, fix:, test:, docs:, docs(tickets):, style:) like the existing history.
Commit dates: set GIT_AUTHOR_DATE and GIT_COMMITTER_DATE (equal) on every commit and merge to the actual current local time, read with "date '+%F %T %z'" right before committing: real seconds, never :00, never in the future. Dates fall on ${A.date} inside working hours 08:30-12:00 or 13:30-17:30 +0700 and stay monotonic. If the current time is outside those windows, use a time a few minutes before the end of the last window that has started today, later than the previous commit, with uneven seconds.
Never push, never add remotes, never delete branches, never touch main. Never commit package-lock.json at the repository root, playwright.local.config.ts or anything under .scratch/. Add no npm dependency.
Never run Prettier on Markdown files or whole folders; only the format-on-edit hook formats code files.
Follow CLAUDE.md and practice/tally/tickets/README.md exactly: compact ticket tables, git mv between status folders, docs/business-rules.md and docs/design.md updated in the same branch, permissions only in worker/policy.ts, user-facing text only in src/i18n/locales with every locale and every error code translated (Vietnamese with proper diacritics, UTF-8 without BOM), \\uXXXX for non-ASCII test input, synthetic names, BEM SCSS with theme custom properties, dialogs through src/hooks/useDialog. No local absolute paths in committed files. A bug fix comes with a test that fails before the fix.
Never read tally-*-answers.md or anything that looks like an answer key.
Files in the main checkout are CRLF: conflict-resolution scripts must match \\r?\\n.
Miniflare "bad port" or hook timeouts and Playwright webServer or browser launch timeouts are known to be flaky: rerun once.
Worktrees get their own "npm ci --no-audit --no-fund" in practice/tally (skip it if node_modules is complete). Never create a node_modules junction or symlink.
Keep working with tool calls until the task is done. Your final answer is the structured output.`

const worktreeSetup = (wt, branch) => `Worktree: if ${wt} does not exist, run "git worktree add -b ${branch} ${wt} develop" (without -b if the branch exists). If it exists, inspect git status and git log and continue there; discard uncommitted leftovers of a stopped run (keep node_modules), never committed work.`

const e2eSetup = (wt, port) => `E2e setup in ${wt}/practice/tally: write playwright.local.config.ts that spreads ./playwright.config, sets use.baseURL to http://localhost:${port}, and sets webServer.env.TALLY_PORT to "${port}", webServer.url to http://localhost:${port}/api/health and reuseExistingServer to false. List playwright.local.config.ts in "$(git rev-parse --git-common-dir)/info/exclude". Run e2e only with "npx playwright test --config playwright.local.config.ts" (never port 5173 or 5174).`

const PLAN_SCHEMA = { type: 'object', properties: {
  baseCommit: { type: 'string', description: 'git rev-parse --short develop when planning started' },
  overview: { type: 'string' },
  items: { type: 'array', items: { type: 'object', properties: {
    name: { type: 'string' },
    instructions: { type: 'string', description: 'complete builder instructions, no code blocks' } },
    required: ['name', 'instructions'] } },
  risks: { type: 'array', items: { type: 'string' } } },
  required: ['baseCommit', 'overview', 'items', 'risks'] }
const BUILD_SCHEMA = { type: 'object', properties: {
  branch: { type: 'string' }, commits: { type: 'array', items: { type: 'string' } },
  tests: { type: 'string' }, unfinished: { type: 'array', items: { type: 'string' } }, summary: { type: 'string' } },
  required: ['branch', 'commits', 'tests', 'unfinished', 'summary'] }
const REVIEW_SCHEMA = { type: 'object', properties: {
  name: { type: 'string' }, ready: { type: 'boolean' }, findings: { type: 'array', items: { type: 'string' } },
  fixes: { type: 'array', items: { type: 'string' } }, checks: { type: 'string' }, openIssues: { type: 'array', items: { type: 'string' } } },
  required: ['name', 'ready', 'findings', 'fixes', 'checks', 'openIssues'] }
const CHUNK_SCHEMA = { type: 'object', properties: {
  tickets: { type: 'array', items: REVIEW_SCHEMA },
  merged: { type: 'array', items: { type: 'string' } } },
  required: ['tickets', 'merged'] }
const BATCH_SCHEMA = { type: 'object', properties: {
  developHead: { type: 'string' }, merged: { type: 'array', items: { type: 'string' } },
  findings: { type: 'array', items: { type: 'string' } }, fixes: { type: 'array', items: { type: 'string' } },
  checks: { type: 'string' }, authorsOk: { type: 'boolean' }, openIssues: { type: 'array', items: { type: 'string' } } },
  required: ['developHead', 'merged', 'findings', 'fixes', 'checks', 'authorsOk', 'openIssues'] }

// Plan: one Opus planner per chunk; every planner sees the whole batch to flag shared files.
phase('Plan')
const plans = await parallel(chunks.map((chunk, c) => () => agent(`${COMMON}
You are the Opus AI team lead planning tickets for Haiku developers. You are read-only: no branches, commits or edits.
Whole batch in merge order (for shared-file awareness):
${listOf(TICKETS)}
${chunks.length > 1 ? `You plan chunk ${c + 1} of ${chunks.length}, these tickets only:\n${listOf(chunk)}\n` : ''}Ticket texts: ${chunk.map(t => `${t.name}: ${ticketSource(t)}`).join('; ')}.
Read the README business overview, docs/business-rules.md, docs/design.md and the affected code. Turn each ticket into complete builder instructions checked against the real code: files and functions, behaviour and edge cases, data and SQL approach (race-safe where money or state changes), tests (failing first for bugs; unit and API tests; e2e specs to add or update), i18n keys with English and Vietnamese text, docs sections. Correct the ticket's outline where the code proves it wrong and say why. List the files other tickets in the batch also touch and how to keep edits small and local.
Ticket handling for the builder: put the ticket in tickets/in-progress/<name>.md on the branch (git mv from todo/backlog, or copy the draft), Assignee "Haiku (developer)", add "## Acceptance criteria" and "## Plan" in sync with the instructions${TICKETS.some(t => t.answers) ? ', and "## Answers" where given' : ''}; commit "docs(tickets): start <name> with a plan". If the batch adds new tickets to the board, only the builder of ${TICKETS[0].name} updates "The next free ID" line in practice/tally/tickets/README.md.
Each item's instructions under about 100 lines, no code blocks. Be efficient (about 40 tool calls). Return baseCommit, overview, items (one per ticket of your chunk), risks.`,
  { label: chunks.length > 1 ? `plan:${c + 1}` : 'plan', phase: 'Plan', model: 'opus', schema: PLAN_SCHEMA })))

const items = plans.filter(Boolean).flatMap(p => p.items)
const missing = TICKETS.filter(t => !items.some(i => i.name === t.name))
if (missing.length) return { stopped: 'plan', missing: missing.map(t => t.name), plans }
const baseCommit = plans.find(Boolean).baseCommit
const overview = plans.filter(Boolean).map(p => p.overview).join('\n\n')
const risks = plans.filter(Boolean).flatMap(p => p.risks)
log(`plan ready from ${baseCommit}; risks: ${risks.join(' | ') || 'none'}`)

// Build: Haiku by default; Sonnet only takes over when Haiku fails or leaves work unfinished.
const build = async (t) => {
  const wt = wtOf(t.branch)
  const prompt = `${COMMON}
You are the Haiku developer on ${t.id} ${t.name}. Ticket text: ${ticketSource(t)}.${t.answers ? `\nAdd to the ticket:\n## Answers\n${t.answers}` : ''}
Batch overview from the planner:
${overview}

Your instructions from the planner:
${items.find(i => i.name === t.name).instructions}

${worktreeSetup(wt, t.branch)}
Steps:
1. Ticket step as instructed, then implement in small commits with unit and API tests, e2e spec updates and docs.
2. In ${wt}/practice/tally run npm run typecheck, npm run lint, npm test and npm run test:hooks; fix until green. Do not run e2e; the batch runs it.
3. git mv the ticket to tickets/waiting-to-merge/ with a "## Merge request" section (branch ${t.branch} into develop, what changed, commands and results) and commit.
Do not merge, do not touch develop or the main checkout, do not remove the worktree.`
  const r = await agent(prompt, { label: `build:${t.name}`, phase: 'Build', model: 'haiku', schema: BUILD_SCHEMA })
  if (r && !r.unfinished.length) return r
  log(`build:${t.name} ${r ? 'unfinished' : 'failed'} on haiku; sonnet takes over`)
  return agent(`${prompt}
A Haiku attempt stopped${r ? ` with unfinished work: ${r.unfinished.join('; ')}` : ''}. Inspect the worktree and finish from where it is; keep committed work.`,
    { label: `build:${t.name}:sonnet`, phase: 'Build', model: 'sonnet', schema: BUILD_SCHEMA })
}

// Thorough mode: Sonnet reviews and fixes each ticket as soon as its build is done.
const review = (b, t) => agent(`${COMMON}
You are the Sonnet QA tester reviewing ${t.id} ${t.name} on branch ${t.branch} in ${wtOf(t.branch)} before the AI team lead's batch review.
Builder report: ${JSON.stringify(b)}
Planner instructions:
${items.find(i => i.name === t.name).instructions}
1. Review "git diff develop...${t.branch}" with the review-checklist skill (.claude/skills/review-checklist/SKILL.md): correctness against the plan and Acceptance criteria, tests (failing first for bugs), security, policy placement, i18n, docs, scope, ticket format, commit authors and dates.
2. Fix real problems on the branch, then rerun npm run typecheck, npm run lint and npm test there.
3. Add "## Review" to the ticket in waiting-to-merge/: "Reviewed by Sonnet (QA tester).", findings, fixes, check counts. Commit "docs(tickets): QA review of ${t.name}". Leave the ticket in waiting-to-merge/.
Set ready=false only if the ticket cannot be made correct. Do not merge.`,
  { label: `review:${t.name}`, phase: 'Review', model: 'sonnet', schema: REVIEW_SCHEMA })

const results = await pipeline(TICKETS,
  t => build(t),
  (b, t) => MODE === 'thorough' && b ? review(b, t).then(rv => ({ build: b, review: rv })) : { build: b, review: null })
const reports = TICKETS.map((t, i) => ({ id: t.id, name: t.name, branch: t.branch, worktree: wtOf(t.branch), ...(results[i] || { build: null }) }))

const reviewSteps = who => `For each ticket:
a. Review "git diff develop...<branch>" with the review-checklist skill: correctness against the plan and Acceptance criteria, tests, security, policy placement, i18n, docs, scope, ticket format, commit authors and dates.
b. Fix real problems on the branch in its worktree; rerun npm run typecheck, npm run lint and npm test there.
c. Add to the ticket's "## Review" section (create it if missing) "Reviewed by ${who}.", findings, fixes and check counts; git mv it to tickets/ready-to-review/ and commit "docs(tickets): review <name> and move it to ready-to-review".
d. If a ticket cannot be made correct, leave it in waiting-to-merge/ and report it in openIssues with ready=false.`

const mergeSteps = (names, fixWt) => `Merge, in this order: ${names.join(', ')} (only tickets that are ready):
- In the main checkout (already on develop; never switch it): git merge --no-ff <branch> -m "Merge branch '<branch>' into 'develop'", with the identity and date rules. Resolve conflicts keeping both sides' behaviour. Run npm run typecheck and npm test in practice/tally after each merge.
Then the batch as a whole:
1. Check every commit in ${baseCommit}..develop: author and committer are the configured git user, dates on ${A.date} inside working hours, not in the future, monotonic, seconds not all :00, no Co-Authored-By. Report authorsOk.
2. Review "git diff ${baseCommit}..develop" for cross-ticket interactions, merge leftovers, i18n completeness and docs consistency (business-rules.md, design.md, the next free ID in tickets/README.md).
3. Final checks on develop's head in ${fixWt} (${worktreeSetup(fixWt, FIX_BRANCH)} Fast-forward it to develop first.) ${e2eSetup(fixWt, E2E_PORT)} Run npm run typecheck, npm run lint, npm test, npm run test:hooks and the full e2e suite.
4. If anything fails or cross-ticket fixes are needed, fix on ${FIX_BRANCH} with tests and merge it --no-ff ("Merge branch '${FIX_BRANCH}' into 'develop'"); rerun until all green.
Do not remove worktrees. Return developHead from "git rev-parse --short develop".`

const planText = names => items.filter(i => names.includes(i.name)).map(i => `### ${i.name}\n${i.instructions}`).join('\n\n')
const fixWt = wtOf(FIX_BRANCH)
const order = TICKETS.map(t => t.name)
let chunkReviews = null
let batch

if (MODE === 'thorough' || chunks.length === 1) {
  // One Opus lead reviews (fast) or re-checks (thorough), merges, cross-reviews and runs e2e.
  phase('Batch review')
  batch = await agent(`${COMMON}
You are the Opus AI team lead doing the batch review. develop was ${baseCommit} when the batch started. Tickets in merge order:
${listOf(TICKETS)}
Builder${MODE === 'thorough' ? ' and Sonnet QA' : ''} reports: ${JSON.stringify(reports)}
Planner instructions:
${planText(order)}

${MODE === 'thorough'
    ? 'Each ticket already had a Sonnet QA review and fixes. Re-check each diff for what QA could miss (cross-cutting design, data model, security, race conditions); fix real problems; then follow steps c and d.'
    : 'There is no per-ticket review step: you review, fix and merge each ticket yourself.'}
${reviewSteps('Opus (AI team lead)')}
${mergeSteps(order, fixWt)}`,
    { label: 'batch-review', phase: 'Batch review', model: 'opus', schema: BATCH_SCHEMA })
} else {
  // Fast mode with more than one chunk: one Opus reviewer per chunk, then one Opus lead merges everything in order.
  // The merge agent stays in the Batch review phase so the fast workflow keeps three phases.
  phase('Batch review')
  chunkReviews = await parallel(chunks.map((chunk, c) => () => agent(`${COMMON}
You are an Opus AI team lead reviewing chunk ${c + 1} of ${chunks.length} of a ticket batch. develop was ${baseCommit} when the batch started. Your tickets:
${listOf(chunk)}
Builder reports: ${JSON.stringify(reports.filter(r => chunk.some(t => t.name === r.name)))}
Planner instructions:
${planText(chunk.map(t => t.name))}
There is no per-ticket review step: you review and fix each ticket. Do NOT merge; another lead merges the whole batch.
${reviewSteps('Opus (AI team lead)')}
Return tickets (one review per ticket) and merged as an empty list.`,
    { label: `batch-review:${c + 1}`, phase: 'Batch review', model: 'opus', schema: CHUNK_SCHEMA })))
  const ready = chunkReviews.filter(Boolean).flatMap(r => r.tickets).filter(r => r.ready).map(r => r.name)
  batch = await agent(`${COMMON}
You are the Opus AI team lead integrating a reviewed ticket batch. develop was ${baseCommit} when the batch started. Tickets:
${listOf(TICKETS)}
Chunk reviews (tickets are in tickets/ready-to-review/ on their branches when ready): ${JSON.stringify(chunkReviews)}
${mergeSteps(order.filter(n => ready.includes(n)), fixWt)}`,
    { label: 'integrate', phase: 'Batch review', model: 'opus', schema: BATCH_SCHEMA })
}

return {
  mode: MODE, baseCommit, overview, risks,
  builds: reports.map(r => ({ name: r.name, unfinished: r.build && r.build.unfinished, tests: r.build && r.build.tests })),
  reviews: MODE === 'thorough' ? reports.map(r => r.review) : chunkReviews,
  batch,
}
